begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select ok(not has_table_privilege('authenticated','private.otp_challenges','select'),'Browser cannot read OTP hashes');
select ok(not has_function_privilege('authenticated','public.rk_otp_consume(uuid,text,text,text,uuid,text)','execute'),'Browser cannot directly validate codes');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.rk_otp_begin('a0000000-0000-4000-8000-000000000001',repeat('a',64),'sms','login',null,null,repeat('b',64)),true,'Challenge reserved');
select is(public.rk_otp_begin('a0000000-0000-4000-8000-000000000002',repeat('a',64),'sms','login',null,null,repeat('b',64)),false,'Cooldown enforced across requests');
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000001',repeat('a',64),'sms','login',null,repeat('b',64)),null::jsonb,'Unconfirmed delivery cannot authenticate');
select public.rk_otp_sent('a0000000-0000-4000-8000-000000000001','12345',true);
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000001',repeat('a',64),'sms','login',null,repeat('c',64)),null::jsonb,'Wrong code denied');
select is((select attempts from private.otp_challenges where id='a0000000-0000-4000-8000-000000000001'),1,'Wrong attempt persists');
select ok(public.rk_otp_consume('a0000000-0000-4000-8000-000000000001',repeat('a',64),'sms','login',null,repeat('b',64)) is not null,'Correct code accepted');
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000001',repeat('a',64),'sms','login',null,repeat('b',64)),null::jsonb,'Replay denied');
select is(public.rk_otp_begin('a0000000-0000-4000-8000-000000000003',repeat('c',64),'sms','login',null,null,repeat('b',64)),true,'Second challenge reserved');
select public.rk_otp_sent('a0000000-0000-4000-8000-000000000003','12346',true);
update private.otp_challenges set expires_at=now()-interval '1 second' where id='a0000000-0000-4000-8000-000000000003';
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000003',repeat('c',64),'sms','login',null,repeat('b',64)),null::jsonb,'Expiry enforced in DB');
update private.otp_challenges set expires_at=now()+interval '5 minutes',attempts=5 where id='a0000000-0000-4000-8000-000000000003';
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000003',repeat('c',64),'sms','login',null,repeat('b',64)),null::jsonb,'Five attempts exhaust challenge');
select ok((select relrowsecurity from pg_class where oid='private.otp_challenges'::regclass),'OTP table enforces RLS');
select is(public.rk_otp_identity('admin@rkmed.test','email'),null::jsonb,'Member OTP cannot downgrade staff authentication');
select is(public.rk_otp_begin('a0000000-0000-4000-8000-000000000010',repeat('d',64),'email','signup',null,null,repeat('b',64)),true,'Signup challenge reserved');
select public.rk_otp_sent('a0000000-0000-4000-8000-000000000010','12347',true);
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000010',repeat('d',64),'sms','signup',null,repeat('b',64)),null::jsonb,'Code cannot switch channel');
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000010',repeat('d',64),'email','login',null,repeat('b',64)),null::jsonb,'Code cannot switch purpose');
update private.otp_challenges set created_at=now()-interval '61 seconds' where id='a0000000-0000-4000-8000-000000000010';
select is(public.rk_otp_begin('a0000000-0000-4000-8000-000000000011',repeat('d',64),'email','signup',null,null,repeat('c',64)),true,'Resend allowed after cooldown');
select is((select status from private.otp_challenges where id='a0000000-0000-4000-8000-000000000010'),'superseded','Resend invalidates older code');
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000010',repeat('d',64),'email','signup',null,repeat('b',64)),null::jsonb,'Superseded code cannot authenticate');
select is(public.rk_otp_begin('a0000000-0000-4000-8000-000000000012',repeat('e',64),'sms','attach','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001',repeat('b',64)),true,'Attachment binds actor');
select public.rk_otp_sent('a0000000-0000-4000-8000-000000000012','12348',true);
select is(public.rk_otp_consume('a0000000-0000-4000-8000-000000000012',repeat('e',64),'sms','attach','00000000-0000-4000-8000-000000000002',repeat('b',64)),null::jsonb,'Attachment cannot be moved to another session owner');
select * from finish();
rollback;
